fields.InputDefinition:
{
  "goal": "In Component Studio → Form Studio, find the view-mode toggle button in the Forms rail header (a list/folder-tree icon, tooltip 'Switch to tree view (Schema → Entity → Form)'). Click it to switch the forms list from the flat list into the grouped tree view. Verify the list re-groups by Schema → Entity → Form (schema headers with database icons, entity sub-groups with per-entity form counts) — or, if there are no forms, that a clean empty state is shown. Toggle back to the flat list to confirm it round-trips. Pages can take 10-30s to load — wait, don't navigate away. Seeing the list restructure between flat and tree layouts is success.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "Clicking the forms-list view toggle switches between the flat list and a Schema → Entity → Form grouped tree",
    "The tree view shows schema group headers and entity sub-groups with form counts (or a valid empty state if no forms exist)",
    "No error messages, blank screens, or crash pages"
  ]
}
